FLASHCARDS = [
    {'id': f'f{i}', 'cat': cat, 'front': front, 'back': back, 'detail': detail}
    for i, (cat, front, back, detail) in enumerate(_FC, 1)
]

# Questions are written as rows per category and numbered in order: q1.. (mc), msq1.. (ms), tf1.. (tf).
_QS = {'mc': [], 'ms': [], 'tf': []}


def _mc(cat, rows):
    for question, options, correct, explanation in rows:
        _QS['mc'].append((cat, question, options, correct, explanation))


def _ms(cat, rows):
    for question, options, correct, explanation in rows:
        _QS['ms'].append((cat, question, options, correct, explanation))


def _tf(cat, rows):
    for question, answer, explanation in rows:
        _QS['tf'].append((cat, question, answer, explanation))


# ---------------------------------------------------------------- multiple choice
